// 60% bài kèm ảnh chụp web, 40% bài chữ + comment link
const rand = Math.random();
const postType = rand < 0.6 ? 'image_post' : 'text_post';

// Danh sách trang web TOEIC viral để lấy content
const viralSources = [
  'https://dethitoeic.com',
  'https://toeichanquoc.com',
  'https://prep.vn/toeic',
  'https://study4.vn/blog',
  'https://ets.org/toeic'
];

// Danh sách trang của website để chụp ảnh
const websitePages = [
  { url: 'http://localhost:3000', label: 'Trang chủ TOEIC Mastery', page: 'home' },
  { url: 'http://localhost:3000/thi-thu-mien-phi', label: 'Thi thử TOEIC miễn phí', page: 'exam' },
  { url: 'http://localhost:3000/vocabulary', label: 'Từ vựng TOEIC', page: 'vocab' },
  { url: 'http://localhost:3000/grammar', label: 'Ngữ pháp TOEIC', page: 'grammar' },
  { url: 'http://localhost:3000/dashboard', label: 'Dashboard học tập', page: 'dashboard' },
  { url: 'http://localhost:3000/tu-vung', label: 'Từ vựng theo chủ đề', page: 'tu-vung' },
  { url: 'http://localhost:3000/tips', label: 'Tips luyện TOEIC', page: 'tips' }
];

// Danh sách viral TOEIC topics để tạo content
const toeicTopics = [
  'Part 5 ngữ pháp hay gặp nhất',
  'Từ vựng TOEIC chủ đề văn phòng',
  'Chiến thuật làm Part 7 nhanh',
  'Lỗi sai thường gặp trong TOEIC',
  'Từ vựng TOEIC chủ đề tài chính',
  'Phương pháp học từ vựng hiệu quả',
  'Part 2 câu hỏi dạng WH',
  'Tips nghe Part 3 và Part 4',
  'Từ đồng nghĩa hay xuất hiện trong TOEIC',
  'Cách đọc hiểu email nhanh Part 7',
  'Grammar: Mệnh đề quan hệ trong TOEIC',
  'Từ vựng TOEIC chủ đề vận chuyển'
];

const randomSource = viralSources[Math.floor(Math.random() * viralSources.length)];
const randomPage = websitePages[Math.floor(Math.random() * websitePages.length)];
const randomTopic = toeicTopics[Math.floor(Math.random() * toeicTopics.length)];

return [{
  json: {
    postType,
    viralSource: randomSource,
    websitePage: randomPage,
    topic: randomTopic,
    timestamp: new Date().toISOString()
  }
}];

const html = $input.first().json?.data || $input.first().json?.body || '';

// Loại bỏ HTML tags, lấy text
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 3000); // Giới hạn 3000 ký tự để gửi cho AI

const prevData = $('Chọn loại bài ngẫu nhiên').first().json;

return [{
  json: {
    ...prevData,
    scrapedText: text || 'Không lấy được nội dung từ web, dùng kiến thức TOEIC chung.'
  }
}];

const data = $input.first().json;
const postType = data.postType || 'text_post';
const topic = data.topic || 'TOEIC tips';
const scrapedText = data.scrapedText || '';
const pageLabel = data.websitePage?.label || 'TOEIC Mastery';
const pageUrl = data.websitePage?.url?.replace('localhost:3000', 'toeicmastery.vn') || 'https://toeicmastery.vn';

let prompt = '';

if (postType === 'image_post') {
  prompt = `Bạn là chuyên gia TOEIC người Việt, đang quản lý trang Threads giáo dục.
Viết 1 bài Threads ngắn (tối đa 500 ký tự) về chủ đề: "${topic}".

Tham khảo nội dung sau để lấy ý tưởng (không copy nguyên văn):
${scrapedText.substring(0, 1500)}

Yêu cầu:
- Viết tiếng Việt tự nhiên, như người thật đang chia sẻ kinh nghiệm học TOEIC
- Mở đầu bằng hook thu hút (câu hỏi, sự thật thú vị, hoặc lời khuyên mạnh)
- Có 3-5 điểm chính dạng bullet (dùng emoji phù hợp)
- Cuối bài: gọi action nhẹ nhàng (ví dụ: "Thử ngay tại link trong bio!" hoặc "Save lại để ôn nhé!")
- KHÔNG đề cập tên website trong bài chính (sẽ comment link riêng)
- Viết như người đã học TOEIC lâu năm, chia sẻ thực tế

Chỉ trả về nội dung bài viết, không giải thích gì thêm.`;
} else {
  prompt = `Bạn là chuyên gia TOEIC người Việt, đang quản lý trang Threads giáo dục.
Viết 1 bài Threads (tối đa 400 ký tự) về chủ đề: "${topic}".

Tham khảo nội dung sau để lấy ý tưởng:
${scrapedText.substring(0, 1500)}

Yêu cầu:
- Viết tiếng Việt tự nhiên, chân thực
- Dạng chia sẻ kinh nghiệm hoặc tip ngắn gọn
- Dùng 2-4 emoji phù hợp
- Cuối bài để trống 1 dòng rồi thêm: "🔗 Luyện tập miễn phí tại: ${pageUrl}"
- Giọng văn thân thiện, không quảng cáo lộ liễu

Chỉ trả về nội dung bài viết, không giải thích gì thêm.`;
}

return [{
  json: {
    ...data,
    prompt,
    pageUrl
  }
}];

const aiResponse = $input.first().json;
const prevData = $('Tạo prompt cho AI').first().json;

// Lấy text từ Gemini response
let generatedContent = '';
try {
  generatedContent = aiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch(e) {
  generatedContent = 'Hôm nay học Part 5 TOEIC nhé! 📚\n\n• Chú ý thì động từ trong câu\n• Phân biệt danh từ/tính từ/trạng từ\n• Practice nhiều là key!\n\n💪 Luyện ngay tại toeicmastery.vn';
}

generatedContent = generatedContent.trim();

// Tạo comment link (nếu là image_post)
let linkComment = '';
if (prevData.postType === 'image_post') {
  const url = prevData.pageUrl || 'https://toeicmastery.vn';
  linkComment = `🔗 Luyện tập miễn phí ngay tại: ${url}\n#TOEIC #HọcTiếngAnh #TOEICMastery #LuyệnThi`;
}

// Thêm hashtag nếu chưa có
const hashtags = '#TOEIC #HọcTiếngAnh #TOEICMastery #LuyệnThiTOEIC';
if (!generatedContent.includes('#TOEIC')) {
  generatedContent += `\n\n${hashtags}`;
}

return [{
  json: {
    ...prevData,
    generatedContent,
    linkComment,
    hasImage: prevData.postType === 'image_post'
  }
}];
